defmodule Perata.WebhookOrder do
  @moduledoc "O pedido como a API o devolve (Order) e, nos eventos que um reembolso causou (order.refunded e o order.updated que o acompanha), o reembolso que o causou. status continua sendo o do checkout (succeeded) depois de um reembolso: order_status e refunded_amount_cents dizem onde o dinheiro está."

  defstruct [
    :amount_cents,
    :client_reference_id,
    :currency,
    :customer_id,
    :cycle_sequence,
    :discount_cents,
    :discount_code,
    :discount_id,
    :id,
    :installment_interest_cents,
    :installments,
    :items,
    :metadata,
    :order_status,
    :paid_at,
    :payment_method_discount_bp,
    :payment_method_discount_cents,
    :period_end,
    :period_start,
    :price_id,
    :product_id,
    :refund_amount_cents,
    :refund_id,
    :refunded_amount_cents,
    :showcase_id,
    :status,
    :subscription_id,
    :subtotal_cents
  ]

  @typedoc """
  * `client_reference_id`: O id do pedido no seu sistema, enviado ao criar o checkout; vazio sem ele. Na renovação de uma assinatura é o do checkout que a vendeu.
  * `currency` (one of `"BRL"`)
  * `cycle_sequence`: O ciclo da assinatura que o pagamento cobra: 1 é o primeiro, 2 é a primeira renovação.
  * `discount_cents`: Quanto o desconto tirou do pedido, em centavos; 0 sem desconto.
  * `discount_code`: O código que o comprador digitou no checkout deste pedido; nulo quando o desconto veio por discount_id, quando veio da assinatura numa renovação ou quando não houve desconto.
  * `discount_id`: O desconto do catálogo que este pedido aplicou; nulo quando não houve desconto. Na renovação de uma assinatura é o desconto que a assinatura aplicou naquele ciclo.
  * `installment_interest_cents`: Juros do parcelamento pagos pelo comprador, cobrados além de amount_cents.
  * `installments`: Em quantas parcelas o cartão de crédito foi cobrado; 1 à vista.
  * `items`: As linhas do pedido, quando o seu servidor as enviou ao criar o checkout; vazio sem elas.
  * `metadata`: Os pares que o seu servidor enviou ao criar o checkout. Na renovação de uma assinatura são os metadados da assinatura (o id da câmera, por exemplo).
  * `order_status` (one of `"pending"`, `"paid"`, `"partially_refunded"`, `"refunded"`): Onde o pedido está; status é o do checkout e continua succeeded depois de um reembolso, e este vira partially_refunded ou refunded.
  * `payment_method_discount_bp`: A taxa do desconto da forma de pagamento, em centésimos de ponto percentual (500 é 5%); 0 sem ele.
  * `payment_method_discount_cents`: Quanto o desconto da forma de pagamento (Pix ou boleto) tirou de amount_cents, em centavos; 0 sem ele. O comprador pagou amount_cents menos este valor. Com cupom que soma, o desconto da forma vem depois do cupom; com cupom que não soma, vale só o maior dos dois e o outro não aparece.
  * `period_end`: O fim do período do ciclo que o pagamento cobra.
  * `period_start`: O início do período do ciclo que o pagamento cobra.
  * `refund_amount_cents`: O valor só deste reembolso, em centavos; nulo como refund_id. O acumulado do pedido é refunded_amount_cents.
  * `refund_id`: O reembolso que causou este evento; nulo nos eventos que nenhum reembolso causou.
  * `refunded_amount_cents`: Quanto do pedido já foi devolvido, somando todos os reembolsos que deram certo, em centavos.
  * `showcase_id`: O showcase da venda.
  * `status` (one of `"open"`, `"confirmed"`, `"succeeded"`, `"failed"`, `"expired"`)
  * `subscription_id`: A assinatura que este pagamento cobra; nulo quando a venda não é de uma assinatura.
  * `subtotal_cents`: O valor do pedido antes do desconto, em centavos: subtotal_cents menos discount_cents é o amount_cents.
  """
  @type t :: %__MODULE__{
          amount_cents: integer(),
          client_reference_id: String.t(),
          currency: String.t(),
          customer_id: String.t(),
          cycle_sequence: integer() | nil,
          discount_cents: integer(),
          discount_code: String.t() | nil,
          discount_id: String.t() | nil,
          id: String.t(),
          installment_interest_cents: integer(),
          installments: integer(),
          items: [Perata.CheckoutLine.t()],
          metadata: %{optional(String.t()) => term()},
          order_status: String.t() | nil,
          paid_at: String.t() | nil,
          payment_method_discount_bp: integer(),
          payment_method_discount_cents: integer(),
          period_end: String.t() | nil,
          period_start: String.t() | nil,
          price_id: String.t(),
          product_id: String.t(),
          refund_amount_cents: integer() | nil,
          refund_id: String.t() | nil,
          refunded_amount_cents: integer(),
          showcase_id: String.t(),
          status: String.t(),
          subscription_id: String.t() | nil,
          subtotal_cents: integer()
        }

  @doc "Builds a WebhookOrder from the API's JSON."
  @spec from_map(map()) :: t()
  def from_map(%{} = data) do
    %__MODULE__{
      amount_cents: Map.fetch!(data, "amount_cents"),
      client_reference_id: Map.fetch!(data, "client_reference_id"),
      currency: Map.fetch!(data, "currency"),
      customer_id: Map.fetch!(data, "customer_id"),
      cycle_sequence: data["cycle_sequence"],
      discount_cents: Map.fetch!(data, "discount_cents"),
      discount_code: data["discount_code"],
      discount_id: data["discount_id"],
      id: Map.fetch!(data, "id"),
      installment_interest_cents: Map.fetch!(data, "installment_interest_cents"),
      installments: Map.fetch!(data, "installments"),
      items: Enum.map(Map.fetch!(data, "items"), &Perata.CheckoutLine.from_map/1),
      metadata: Map.fetch!(data, "metadata"),
      order_status: data["order_status"],
      paid_at: data["paid_at"],
      payment_method_discount_bp: Map.fetch!(data, "payment_method_discount_bp"),
      payment_method_discount_cents: Map.fetch!(data, "payment_method_discount_cents"),
      period_end: data["period_end"],
      period_start: data["period_start"],
      price_id: Map.fetch!(data, "price_id"),
      product_id: Map.fetch!(data, "product_id"),
      refund_amount_cents: data["refund_amount_cents"],
      refund_id: data["refund_id"],
      refunded_amount_cents: Map.fetch!(data, "refunded_amount_cents"),
      showcase_id: Map.fetch!(data, "showcase_id"),
      status: Map.fetch!(data, "status"),
      subscription_id: data["subscription_id"],
      subtotal_cents: Map.fetch!(data, "subtotal_cents")
    }
  end
end

